import { escapeHTML as e, number, percent, dateLabel } from "./lib.js?v=28aacea7ef76";
import { ratioLabel } from "./efficiency.js?v=28aacea7ef76";

const short = value => value ? value.slice(0, 10) : "—";
const field = (label, value) => `<div class="experiment-field"><h3>${e(label)}</h3><p class="prose">${e(value)}</p></div>`;
const openRound = (card, text = "Open lessons & assessment ↗") => `<button class="text-button" data-experiment-round="${e(card.round_id)}" data-experiment-campaign="${e(card.campaign_id)}">${e(text)}</button>`;
const delta = value => Number.isFinite(value) ? `${value > 0 ? "+" : ""}${number(value * 100, 1)} pp` : "—";

function pairedEvidence(assessment = {}) {
  const rows = assessment.paired || [];
  if (!rows.length) return `<p class="quiet">${assessment.requested_pairs === 0 ? "No same-question comparison was requested." : assessment.status !== "complete" ? "Completed assessment evidence is not available yet." : "No paired assessment was recorded."}</p>`;
  return `<div class="table-scroll"><table><caption>Same-question online evidence</caption><thead><tr><th>Question</th><th>Before</th><th>After</th><th>Change</th></tr></thead><tbody>${rows.map(row => `<tr><th>${e(row.question || row.id)}<small>${!row.weights_changed ? "Weights unchanged · one observation reused" : !row.comparable ? "Generation conditions do not match" : "Matched recorded generation conditions"}</small></th><td>${percent(row.before_score)}</td><td>${percent(row.after_score)}</td><td>${delta(row.score_delta)}</td></tr>`).join("")}</tbody></table></div><p class="quiet">These questions describe this iteration. Scores from different question sets do not form a comparable learning curve.</p>`;
}

function measuredWork(work) {
  if (!work || work.error) return `<p class="quiet">${e(work?.error || "Measured training work is not available yet.")}</p>`;
  const measured = work.measured_work_all_attempts || {}, efficiency = work.teacher_efficiency || {};
  const authors = work.material_author_work;
  const authorReported = authors && authors.calls_without_usage < authors.calls
    && Number.isFinite(authors.reported_input_tokens) && Number.isFinite(authors.reported_output_tokens);
  return `<dl class="experiment-metrics"><div><dt>Trained targets</dt><dd>${number(measured.tokens)}</dd><span>All passes and attempts</span></div><div><dt>Teacher tokens</dt><dd>${Number.isFinite(efficiency.teacher_tokens) ? number(efficiency.teacher_tokens) : "—"}</dd><span>${efficiency.status === "complete" ? "Input + output reported" : "Usage incomplete or unavailable"}</span></div><div><dt>Training efficiency</dt><dd>${ratioLabel(efficiency.ratio)}</dd><span>Trained / Teacher tokens</span></div><div><dt>Material Author tokens</dt><dd>${authorReported ? number(authors.reported_input_tokens + authors.reported_output_tokens) : "—"}</dd><span>${authors ? `${number(authors.calls)} calls · ${number(authors.calls_without_usage)} incomplete${authors.calls_without_usage ? " · partial usage" : ""}` : "No author calls recorded"}</span></div></dl><p class="quiet">Exposure includes repetition and retries. This ratio measures throughput; learning evidence is shown separately.</p>`;
}

export function experimentCard(card, work = card?.learning_work) {
  if (!card) return "";
  if (card.error) return `<p class="notice" role="status">${e(card.error)}</p>`;
  const plan = card.plan, review = card.review;
  const status = review ? { ongoing: "Investigation ongoing", concluded: "Teacher conclusion recorded", abandoned: "Investigation abandoned" }[review.status] : "No Teacher conclusion recorded";
  return `<article class="panel experiment-card"><div class="panel-heading"><div><div class="eyebrow">Teaching experiment · iteration ${number(card.round_number)}</div><h2>${e(plan.title)}</h2><p class="quiet">Planned ${e(dateLabel(card.planned_at))} · execution ${e(card.execution.status)}</p></div></div><div class="experiment-body">${field("Hypothesis · recorded before training", plan.hypothesis)}<div class="experiment-plan-grid">${field("Intervention", plan.intervention)}${field("Evidence to inspect", plan.observation_plan)}${field("Budget basis", plan.budget_basis)}${field("Reconsider if", plan.reconsider_if)}</div><details class="context-details" data-detail="experiment-strategy-${e(card.id)}"><summary>Strategy · ${e(card.strategy.name)} · ${e(short(card.strategy_version))}</summary><p class="prose">${e(card.strategy.approach)}</p><p><button class="text-button" id="experiment-strategy-${e(card.id)}" data-experiment-strategy="${e(card.strategy_version)}">All experiments using this version →</button>${card.strategy.parent_version ? ` · <button class="text-button" id="experiment-parent-${e(card.id)}" data-experiment-strategy="${e(card.strategy.parent_version)}">Parent version ${e(short(card.strategy.parent_version))} →</button>` : ""}</p><p class="quiet">Starting checkpoint <code>${e(card.starting_point.checkpoint)}</code></p><p class="quiet">Plan artifact <code>${e(card.artifacts.select.hash)}</code></p>${card.related_rounds?.length ? `<p>Related teaching: ${card.related_rounds.filter(Boolean).map(round => openRound(round, `${short(round.campaign_id.replace(/^campaign_/, ""))} · iteration ${round.round_number}`)).join(" · ")}</p>` : ""}</details><section class="experiment-conclusion"><h3>${e(status)}</h3>${review ? `${field("Teacher findings", review.findings)}${field("Limitations", review.limitations)}${field("Next action", review.next_action)}${review.evaluation_ids.length ? `<p class="quiet">Cited questions: ${review.evaluation_ids.map(e).join(", ")}</p>` : ""}` : '<p class="quiet">The pre-training plan is preserved. A later reflection can record findings, including no observed improvement.</p>'}</section><h3>Recorded work & evidence</h3>${measuredWork(work)}${pairedEvidence(card.assessment)}<p class="quiet">Sequential teaching observation. Diagnostic questions are frozen before answers, after training. This is not a matched-start A/B comparison.</p>${openRound(card)}</div></article>`;
}

export function experimentsView(browser = {}) {
  const page = browser.page, items = page?.items || [];
  const filter = browser.strategyVersion;
  return `<section class="experiments"><div class="section-heading"><div><h2>Teaching experiments</h2><p class="quiet">All runs and continuations · hypotheses, strategy versions and recorded evidence</p></div>${browser.loading ? '<span class="quiet" role="status">Updating…</span>' : ""}</div>${filter ? `<p class="experiment-filter">Strategy <code>${e(short(filter))}</code> <button class="text-button" id="experiment-clear-filter" data-experiment-strategy="">Show all strategies</button></p>` : ""}${browser.error ? `<p class="notice" role="status">${e(browser.error)} <button class="text-button" data-experiment-refresh>Retry</button></p>` : ""}<div class="experiment-layout"><div class="experiment-register"><div class="panel">${items.length ? items.map(row => `<button class="experiment-row ${row.round_id === browser.selectedId ? "selected" : ""}" data-experiment-select="${e(row.round_id)}" ${row.round_id === browser.selectedId ? 'aria-current="true"' : ""}><span class="eyebrow">Iteration ${number(row.round_number)} · ${e(row.execution_status)}</span><strong>${e(row.title)}</strong><span>${e(row.hypothesis)}</span><small>${e(row.strategy_name)} · ${e(short(row.strategy_version))}</small><small>${e(dateLabel(row.planned_at))} · ${e(row.campaign_name)}</small></button>`).join("") : `<div class="empty-inline">${!page ? "Loading teaching experiments…" : "No teaching experiments recorded for this selection."}</div>`}</div><div class="experiment-pagination"><span class="quiet">${page ? `${number(page.total)} recorded` : ""}</span>${browser.before !== null && browser.before !== undefined ? '<button class="text-button" data-experiment-page="latest">Latest</button>' : ""}${page?.next_before ? `<button class="button secondary" data-experiment-page="${page.next_before}">Older experiments →</button>` : ""}</div></div><div class="experiment-selection">${browser.detail ? experimentCard(browser.detail) : browser.detailLoading ? '<div class="empty-inline" role="status">Loading experiment evidence…</div>' : page && !items.length ? '<div class="empty-inline">Teacher plans appear here when an explicit experiment is recorded. Earlier lessons and assessments remain available in their iterations.</div>' : ""}</div></div></section>`;
}
